  AppleHLG:
    "\n  \n  vec3 invOutputTransform_AppleHLG(vec3 In, float Y_MIN, float Y_MID, float Y_MAX, Chromaticities DISPLAY_PRI, Chromaticities LIMITING_PRI, int EOTF, int SURROUND, bool STRETCH_BLACK, bool D60_SIM, bool LEGAL_RANGE) {\n    mat3 DISPLAY_PRI_2_XYZ_MAT = RGBtoXYZ( DISPLAY_PRI);\n    TsParams PARAMS_DEFAULT = init_TsParams( Y_MIN, Y_MAX, 0.0);\n    float expShift = log2(inv_ssts(Y_MID, PARAMS_DEFAULT)) - log2(0.18);\n    TsParams PARAMS = init_TsParams( Y_MIN, Y_MAX, expShift);\n    vec3 outputCV = In;\n    if (LEGAL_RANGE == true) {\n      outputCV = smpteRange_to_fullRange_f3( outputCV);\n    }\n    vec3 linearCV;\n    if (EOTF == 0) {\n      if (STRETCH_BLACK == true) {\n        linearCV = Y_2_linCV_f3( ST2084_2_Y_f3( outputCV), Y_MAX, 0.0);\n      } else {\n        linearCV = Y_2_linCV_f3( ST2084_2_Y_f3( outputCV), Y_MAX, Y_MIN);\n      }\n    } else if (EOTF == 1) {\n      linearCV = bt1886_f_f3( outputCV, 2.4, 1.0, 0.0);\n    } else if (EOTF == 2) {\n      linearCV = moncurve_f_f3( outputCV, 2.4, 0.055);\n    } else if (EOTF == 3) {\n      linearCV = pow_f3( outputCV, 2.6);\n    } else if (EOTF == 4) {\n      linearCV = Y_2_linCV_f3( outputCV, Y_MAX, Y_MIN);\n    } else if (EOTF == 5) {\n      outputCV = HLG_2_ST2084_1000nits_f3( outputCV);\n      if (STRETCH_BLACK == true) {\n        linearCV = Y_2_linCV_f3( ST2084_2_Y_f3( outputCV), Y_MAX, 0.0);\n      } else {\n        linearCV = Y_2_linCV_f3( ST2084_2_Y_f3( outputCV), Y_MAX, Y_MIN);\n      }\n    }\n    if (D60_SIM == true) {\n      float SCALE = 1.0;\n      if ((DISPLAY_PRI.white.x == 0.3127) && (DISPLAY_PRI.white.y == 0.329)) {\n        SCALE = 0.96362;\n        linearCV = linearCV * (1.0 / SCALE);\n      } else if ((DISPLAY_PRI.white.x == 0.314) && (DISPLAY_PRI.white.y == 0.351)) {\n        SCALE = 0.96;\n        linearCV.x = roll_white_rev( linearCV.x / SCALE, 0.918, 0.5);\n        linearCV.y = roll_white_rev( linearCV.y / SCALE, 0.918, 0.5);\n        linearCV.z = roll_white_rev( linearCV.z / SCALE, 0.918, 0.5);\n      }\n    }\n    vec3 XYZ = DISPLAY_PRI_2_XYZ_MAT * linearCV;\n    if (D60_SIM == false) {\n      if ((DISPLAY_PRI.white.x != AP0.white.x) && (DISPLAY_PRI.white.y != AP0.white.y)) {\n        XYZ = invert_f33(D60_2_D65_CAT) * XYZ;\n      }\n    }\n    \n    if (SURROUND == 0) {\n    \n    } else if (SURROUND == 1) {\n      if ((EOTF == 1) || (EOTF == 2) || (EOTF == 3)) {\n        XYZ = dim_to_dark( XYZ);\n      }\n    } else if (SURROUND == 2) {\n    \n    }\n    linearCV = XYZ_2_AP1_MAT * XYZ;\n    vec3 rgbPost = linCV_2_Y_f3( linearCV, Y_MAX, Y_MIN);\n    vec3 rgbPre = inv_ssts_f3( rgbPost, PARAMS);\n    vec3 aces = inv_rrt_sweeteners( rgbPre);\n    return aces;\n  }\n\n  \n  \n  vec3 CIO_IDT_AppleHLG(vec3 cv) {\n    const float Y_MIN = 0.0001;\n    const float Y_MID = 15.0;\n    const float Y_MAX = 1000.0;\n    Chromaticities DISPLAY_PRI = REC2020_PRI;\n    Chromaticities LIMITING_PRI = REC2020_PRI;\n    int EOTF = 5;\n    int SURROUND = 0;\n    bool STRETCH_BLACK = true;\n    bool D60_SIM = false;\n    bool LEGAL_RANGE = false;\n    vec3 oces = invOutputTransform_AppleHLG(cv, Y_MIN, Y_MID, Y_MAX, DISPLAY_PRI, LIMITING_PRI, EOTF, SURROUND, STRETCH_BLACK, D60_SIM, LEGAL_RANGE);\n    oces = CIO_GAMUT_COMPRESS(oces);\n    return vGamma(ACES_to_ACEScct(oces));\n  }\n",
  AppleLog:
    "\n  \n  \n  float appleLogToLinear_AppleLog(float x)  {\n    const float R_0 = -0.05641088;\n    const float R_t = 0.01;\n    const float c = 47.28711236;\n    const float beta = 0.00964052;\n    const float gamma = 0.08550479;\n    const float delta = 0.69336945;\n    const float P_t = c * pow(R_t - R_0, 2.0);\n    if (x >= P_t) {\n      return pow(2.0, (x - delta) / gamma) - beta;\n    } else if (x >= 0.0 && x < P_t) {\n      return sqrt(x / c) + R_0;\n    } else {\n      return R_0;\n    }\n  }\n  vec3 CIO_IDT_AppleLog(vec3 AppleLog) {\n    float r_lin = appleLogToLinear_AppleLog(AppleLog.x);\n    float g_lin = appleLogToLinear_AppleLog(AppleLog.y);\n    float b_lin = appleLogToLinear_AppleLog(AppleLog.z);\n    vec3 aces = max(vec3(\n      r_lin * 0.6788911506598102 + g_lin * 0.15886842237789234 + b_lin * 0.16224042703562752,\n      r_lin * 0.04557083087232135 + g_lin * 0.8607127720474108 + b_lin * 0.0937163970408747,\n      r_lin * -0.0004857103518124508 + g_lin * 0.025060195735059528 + b_lin * 0.9754255145687619\n    ), 0.0);\n    aces = CIO_GAMUT_COMPRESS(aces);\n    return vGamma(ACES_to_ACEScct(aces));\n  }\n",
  FILM_ADX10:
    "\n  \n  \n  vec3 ADX10_to_ACES_FILM_ADX10(vec3 ADX10) {\n    float LUT_IN[11];\n    LUT_IN[0] = -0.19;\n    LUT_IN[1] = 0.01;\n    LUT_IN[2] = 0.028;\n    LUT_IN[3] = 0.054;\n    LUT_IN[4] = 0.095;\n    LUT_IN[5] = 0.145;\n    LUT_IN[6] = 0.22;\n    LUT_IN[7] = 0.3;\n    LUT_IN[8] = 0.4;\n    LUT_IN[9] = 0.5;\n    LUT_IN[10] = 0.6;\n    float LUT_OUT[11];\n    LUT_OUT[0] = -6.0;\n    LUT_OUT[1] = -2.721718645;\n    LUT_OUT[2] = -2.521718645;\n    LUT_OUT[3] = -2.321718645;\n    LUT_OUT[4] = -2.121718645;\n    LUT_OUT[5] = -1.921718645;\n    LUT_OUT[6] = -1.721718645;\n    LUT_OUT[7] = -1.521718645;\n    LUT_OUT[8] = -1.321718645;\n    LUT_OUT[9] = -1.121718645;\n    LUT_OUT[10] = -0.926545676714876;\n    vec3 adx;\n    adx.x = ADX10.x * 1023.0;\n    adx.y = ADX10.y * 1023.0;\n    adx.z = ADX10.z * 1023.0;\n    vec3 cdd = ( adx - 95.0) / 500.0;\n    vec3 cid = CDD_TO_CID * cdd;\n    vec3 logE;\n    if ( cid.x <= 0.6) logE.x = interpolate1D11( LUT_IN, LUT_OUT, cid.x);\n    if ( cid.y <= 0.6) logE.y = interpolate1D11( LUT_IN, LUT_OUT, cid.y);\n    if ( cid.z <= 0.6) logE.z = interpolate1D11( LUT_IN, LUT_OUT, cid.z);\n    if ( cid.x > 0.6) logE.x = ( 100.0 / 55.0) * cid.x - REF_PT;\n    if ( cid.y > 0.6) logE.y = ( 100.0 / 55.0) * cid.y - REF_PT;\n    if ( cid.z > 0.6) logE.z = ( 100.0 / 55.0) * cid.z - REF_PT;\n    vec3 exp;\n    exp.x = pow( 10.0, logE.x);\n    exp.y = pow( 10.0, logE.y);\n    exp.z = pow( 10.0, logE.z);\n    vec3 aces = EXP_TO_ACES * exp;\n    return max(aces, 0.0);\n  }\n  vec3 CIO_IDT_FILM_ADX10(vec3 adx10) {\n    vec3 aces = ADX10_to_ACES_FILM_ADX10(adx10);\n    aces = CIO_GAMUT_COMPRESS(aces);\n    return vGamma(ACES_to_ACEScct(aces));\n  }\n",
